package com.docgen.service

import java.io.{ByteArrayOutputStream, File}
import java.security.MessageDigest
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import scala.collection.mutable
import scala.util.Try

// Cross-service authentication token validator
object AuthValidator {
  // Fail closed: require the secret to be provided via environment.
  private val serviceSecret: String = sys.env.get("SERVICE_SECRET") match {
    case Some(s) if s.trim.nonEmpty => s
    case _ =>
      throw new IllegalStateException("SERVICE_SECRET environment variable must be set to a strong secret")
  }

  def validateServiceToken(token: String, serviceId: String): Boolean = {
    if (token == null || serviceId == null) return false
    val parts = token.split("\\.")
    if (parts.length != 3) return false
    val header = parts(0)
    val payload = parts(1)
    val signature = parts(2)
    // Bind the signature to the serviceId so a token cannot be reused across services.
    val expectedSig = computeHmac(s"$serviceId.$header.$payload", serviceSecret)
    constantTimeEquals(signature, expectedSig)
  }

  private def constantTimeEquals(provided: String, expected: String): Boolean = {
    Try {
      val a = Base64.getUrlDecoder.decode(provided)
      val b = Base64.getUrlDecoder.decode(expected)
      MessageDigest.isEqual(a, b)
    }.getOrElse(false)
  }

  private def computeHmac(data: String, secret: String): String = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(secret.getBytes("UTF-8"), "HmacSHA256"))
    Base64.getUrlEncoder.withoutPadding.encodeToString(mac.doFinal(data.getBytes("UTF-8")))
  }
}

// Template engine for PDF content generation
object TemplateEngine {
  private val templateCache = mutable.Map[String, String]()

  // Registered safe formatters that process template directives
  private val formatters: Map[String, (String, Map[String, Any]) => String] = Map(
    "text" -> formatText,
    "date" -> formatDate,
    "currency" -> formatCurrency,
    "table" -> formatTable
  )

  def formatText(pattern: String, ctx: Map[String, Any]): String = {
    ctx.foldLeft(pattern) { case (acc, (key, value)) =>
      acc.replace(s"{{$key}}", value.toString)
    }
  }

  def formatDate(pattern: String, ctx: Map[String, Any]): String = {
    val dateVal = ctx.getOrElse("value", "").toString
    s"<date format='$pattern'>$dateVal</date>"
  }

  def formatCurrency(pattern: String, ctx: Map[String, Any]): String = {
    val amount = ctx.getOrElse("amount", "0").toString
    val symbol = ctx.getOrElse("symbol", "$").toString
    s"$symbol$amount"
  }

  def formatTable(pattern: String, ctx: Map[String, Any]): String = {
    val rows = ctx.getOrElse("rows", List.empty).asInstanceOf[List[Map[String, String]]]
    rows.map(row => row.values.mkString(" | ")).mkString("\n")
  }

  def renderTemplate(templateId: String, sections: List[Section]): String = {
    val builder = new StringBuilder
    sections.foreach { section =>
      val formatter = formatters.getOrElse(section.formatterType, formatText)
      builder.append(formatter(section.pattern, section.context))
      builder.append("\n")
    }
    builder.toString()
  }
}

case class Section(
  formatterType: String,
  pattern: String,
  context: Map[String, Any]
)

// PDF generation request handler
class PdfGenerationHandler {

  def handleRequest(request: GenerationRequest): Either[String, Array[Byte]] = {
    // Step 1: Validate cross-service auth
    if (!AuthValidator.validateServiceToken(request.authToken, request.serviceId)) {
      return Left("Authentication failed")
    }

    // Step 2: Parse document specification
    val sections = parseDocumentSpec(request.documentSpec)

    // Step 3: Render content through template engine
    val renderedContent = TemplateEngine.renderTemplate(request.templateId, sections)

    // Step 4: Generate PDF bytes
    Right(generatePdfBytes(renderedContent))
  }

  private def parseDocumentSpec(spec: Map[String, Any]): List[Section] = {
    val rawSections = spec.getOrElse("sections", List.empty).asInstanceOf[List[Map[String, Any]]]
    rawSections.map { raw =>
      Section(
        formatterType = raw.getOrElse("type", "text").toString,
        pattern = raw.getOrElse("pattern", "").toString,
        context = raw.getOrElse("context", Map.empty).asInstanceOf[Map[String, Any]]
      )
    }
  }

  private def generatePdfBytes(content: String): Array[Byte] = {
    // Simplified PDF generation - in production would use iText or Apache PDFBox
    val header = "%PDF-1.4\n"
    val body = s"1 0 obj\n<< /Type /Catalog >>\nendobj\n2 0 obj\n<< /Type /Page /Contents 3 0 R >>\nendobj\n3 0 obj\n<< /Length ${content.length} >>\nstream\n$content\nendstream\nendobj\n"
    (header + body).getBytes("UTF-8")
  }
}

case class GenerationRequest(
  authToken: String,
  serviceId: String,
  templateId: String,
  documentSpec: Map[String, Any]
)

// Service entry point
object PdfService {
  val handler = new PdfGenerationHandler()

  def processRequest(token: String, serviceId: String, templateId: String,
                     spec: Map[String, Any]): Either[String, Array[Byte]] = {
    val request = GenerationRequest(token, serviceId, templateId, spec)
    handler.handleRequest(request)
  }
}
